using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace XHLLauncher {
 public sealed class BackupScheduleRecord {public DateTime NextUtc,LastAttemptUtc,LastSuccessUtc;public int Failures;public bool Paused;public string Outcome="No attempt recorded";public string Phase="Waiting";}
 public sealed class BackupPlan {
  readonly string path;public BackupScheduleRecord State{get;private set;}
  public BackupPlan(string file,int minutes){path=file;State=new BackupScheduleRecord{NextUtc=DateTime.UtcNow.AddMinutes(Math.Max(5,minutes))};if(File.Exists(path))try{State=new JavaScriptSerializer().Deserialize<BackupScheduleRecord>(File.ReadAllText(path));if(State==null||State.NextUtc==DateTime.MinValue)throw new IOException();if(State.Phase=="Copying"){State.Paused=true;State.Outcome="Earlier copy has no recorded outcome. Review incomplete copies before retrying.";}}catch{State=new BackupScheduleRecord{Paused=true,Outcome="Backup schedule is unreadable. Automatic copies paused."};}else try{Save();}catch{State.Paused=true;State.Outcome="Initial backup schedule could not be saved. Automatic copies paused.";}}
  void Save(){Directory.CreateDirectory(Path.GetDirectoryName(path));string tmp=path+".pending";File.WriteAllText(tmp,new JavaScriptSerializer().Serialize(State));if(File.Exists(path))File.Replace(tmp,path,path+".bak");else File.Move(tmp,path);}
  public bool Due(bool enabled,bool busy,DateTime now){return enabled&&!busy&&!State.Paused&&now>=State.NextUtc;}
  public void Begin(int minutes,DateTime now){State.LastAttemptUtc=now;State.NextUtc=now.AddMinutes(Math.Max(5,minutes));State.Paused=false;State.Phase="Copying";Save();}
  public void Finish(bool success,string message,int minutes,DateTime now){State.Phase="Waiting";State.Outcome=message;if(success){State.LastSuccessUtc=now;State.Failures=0;State.Paused=false;State.NextUtc=now.AddMinutes(Math.Max(5,minutes));}else{State.Failures++;State.NextUtc=now.AddMinutes(Math.Min(60,5*Math.Pow(2,State.Failures-1)));if(State.Failures>=3)State.Paused=true;}try{Save();}catch{State.Paused=true;State.Outcome="Backup finished, but schedule persistence failed. Automatic copies paused.";}}
 }
 public sealed class ResilienceRecord {public bool ManualPause;public bool Pending;public bool Armed;public DateTime DueUtc;public List<DateTime> Attempts=new List<DateTime>();public string Phase="Observing";public string Detail="Waiting for fresh process and query evidence.";}
 public sealed class ResilienceGuard {
  readonly string path;public ResilienceRecord State{get;private set;}public bool Locked{get;private set;}bool seenRunning;DateTime healthySince;int failedQueries;
  public ResilienceGuard(string file){path=file;State=new ResilienceRecord();if(File.Exists(path))try{State=new JavaScriptSerializer().Deserialize<ResilienceRecord>(File.ReadAllText(path));if(State==null||State.Attempts==null||State.Attempts.Count>100||State.Attempts.Any(t=>t>DateTime.UtcNow.AddMinutes(5)))throw new IOException("Invalid recovery journal");if(State.Phase=="Recovering"){Locked=true;State.Pending=false;State.Armed=false;State.Phase="Needs review";State.Detail="An earlier recovery did not record its outcome. No repeat start is assumed safe.";}}catch{Locked=true;State=new ResilienceRecord{Phase="Needs review",Detail="Recovery journal cannot be read. Automatic starts are blocked."};}}
  void Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(path));string tmp=path+".pending";File.WriteAllText(tmp,new JavaScriptSerializer().Serialize(State));if(File.Exists(path))File.Replace(tmp,path,path+".bak");else File.Move(tmp,path);}catch{Locked=true;State.Pending=false;State.Armed=false;State.Phase="Needs review";State.Detail="Recovery journal could not be saved. Automatic starts are blocked.";}}
  public void ManualStop(){State.ManualPause=true;State.Pending=false;State.Armed=false;healthySince=DateTime.MinValue;State.Phase="Paused";State.Detail="You stopped the server. Recovery will not undo that choice.";Save();}
  public void ManualStart(){State.ManualPause=false;State.Pending=false;State.Armed=false;healthySince=DateTime.MinValue;State.Detail="Manual start requested; waiting for query-confirmed stability.";Save();}
  public bool Poll(bool enabled,bool running,bool responsive,bool busy,DateTime now){
   State.Attempts.RemoveAll(t=>now-t>TimeSpan.FromHours(1));
   if(!enabled&&(State.Armed||State.Pending)){State.Armed=false;State.Pending=false;Save();}
   if(running){seenRunning=true;if(State.Pending){State.Pending=false;Save();}if(!responsive){healthySince=DateTime.MinValue;failedQueries++;if(!Locked&&!State.ManualPause){State.Phase="Degraded";State.Detail="Process exists; game query is unconfirmed. Observe only — no automatic restart.";}return false;}failedQueries=0;if(healthySince==DateTime.MinValue)healthySince=now;if(!Locked&&!State.ManualPause){State.Phase="Healthy";State.Detail=enabled?"Process and game query are healthy. Recovery is bounded to two attempts per hour.":"Health monitoring active. Automatic recovery is off.";if(enabled&&!State.Armed&&now-healthySince>=TimeSpan.FromSeconds(30)){State.Armed=true;Save();}}return false;}
   healthySince=DateTime.MinValue;if(seenRunning){seenRunning=false;if(State.Armed&&!State.ManualPause&&!Locked){State.Pending=true;State.DueUtc=now.AddSeconds(60+60*State.Attempts.Count);State.Armed=false;State.Phase="Cooling down";State.Detail="An observed healthy process exited. Waiting before a checked recovery attempt.";Save();}}
   if(Locked||State.ManualPause)return false;if(!enabled){State.Phase="Observing";State.Detail="Server offline; automatic recovery is off.";return false;}if(!State.Pending){if(State.Phase!="Recovering"&&State.Phase!="Needs review"){State.Phase="Observing";State.Detail="Server offline. No armed crash recovery is pending.";}return false;}
   if(State.Attempts.Count>=2){State.Pending=false;State.Phase="Needs review";State.Detail="Recovery budget exhausted: two attempts in one hour. Manual review required.";Save();return false;}if(busy||now<State.DueUtc)return false;
   State.Pending=false;State.Attempts.Add(now);State.Phase="Recovering";State.Detail="Recovery attempt recorded before invoking the verified startup path.";Save();return !Locked;
  }
  public void Complete(bool success,string message){State.Phase=success?"Verifying recovery":"Needs review";State.Detail=message;Save();}
 }
 public static class ConfigAlignment {
  public static Dictionary<string,decimal> Proposed(Dictionary<string,object> data){var result=new Dictionary<string,decimal>();foreach(var f in ConfigurationDocument.Flatten(data)){if(!f.Path.StartsWith("gameSettings.")||!(f.Value is ValueType)||f.Value is bool)continue;decimal min,max;if(!ConfigurationDocument.Bounds(f.Key,out min,out max))continue;decimal n=Convert.ToDecimal(f.Value);if(f.Key=="dayTimeDuration"||f.Key=="nightTimeDuration"||f.Key=="fromHungerToStarving")n/=60000000000m;if(n<min||n>max)result[f.Path]=Math.Max(min,Math.Min(max,n));}return result;}
 }
}
